import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%81%B2%E3%81%96%E3%81%AE%E4%B8%8A%E3%83%86%E3%83%BC%E3%83%96%E3%83%AB.html","title":"ひざの上テーブル","lang":"en-US","frontmatter":{},"git":{"createdTime":1650726843000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":6}]},"readingTime":{"minutes":1.78,"words":533},"filePathRelative":"ひざの上テーブル.md"}`),a={name:`ひざの上テーブル.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="ひざの上テーブル" tabindex="-1"><a class="header-anchor" href="#ひざの上テーブル"><span>ひざの上テーブル</span></a></h1><p><a href="./グッズ関連.html">グッズ関連</a></p><h2 id="膝の上で折りたたみキーボードとタブレット使いたい問題" tabindex="-1"><a class="header-anchor" href="#膝の上で折りたたみキーボードとタブレット使いたい問題"><span>膝の上で折りたたみキーボードとタブレット使いたい問題</span></a></h2><p><a href="./Rhinocs.html">Rhinocs</a>がいい感じになってきたので膝の上で使いたい感じがしている。</p><ul><li><a href="https://note.com/naru_tot/n/n498225552923" target="_blank" rel="noopener noreferrer">クリップボードを巡る冒険 Season2｜naru@Master Of Life</a></li><li><a href="https://note.com/rydeen/n/na08339f22b39" target="_blank" rel="noopener noreferrer">1/5_Surfaceタイプの2 in 1を膝の上で快適に使う方法！｜Rydeen</a><ul><li>これは今だとこれっぽい<a href="https://www.amazon.co.jp/dp/B0872Q47T6?&amp;linkCode=ll2&amp;tag=karino203-22&amp;linkId=4b27f817c40bdbba5055cc836a292439&amp;ref_=as_li_ss_tl" target="_blank" rel="noopener noreferrer">amazon: サンワサプライ ノートパソコン用アルミスタンド</a></li></ul></li><li><a href="https://namagusabose.com/2021/02/25/surfacepro_case/" target="_blank" rel="noopener noreferrer">ひざの上で使えるようになったSurfacePro。ケースがすごい - なまぐサラリーマンの快適な壱日</a><ul><li>これは今だとこれか？ <a href="https://www.amazon.co.jp/dp/B08Q6DHTR4?th=1&amp;linkCode=ll2&amp;tag=karino203-22&amp;linkId=f17ab544f967a7c4d8fa98d0fd7d10a2&amp;ref_=as_li_ss_tl" target="_blank" rel="noopener noreferrer">amazon: 保護 ケース サーフェス用 プロ</a></li></ul></li><li><a href="https://studiodo.exblog.jp/26125283/" target="_blank" rel="noopener noreferrer">可変角度タブレットスタンドの自作 : かばぱぱのへだら日記</a></li><li><a href="https://bazadayo.blogspot.com/2016/02/miix-2-8pc.html" target="_blank" rel="noopener noreferrer">ばざのメモ: Miix 2 8を再度購入してみた話（自作スタンド作成＆ノートPC化）</a> ヒンジの情報が。自作するなら参考になりそう。</li><li><a href="https://note.com/maru_hashikami_/n/nbcb37cbdc84a" target="_blank" rel="noopener noreferrer">Surface Pro 12インチ をソファで快適に使いたい！膝上テーブルの選定で悩んだ結果｜degai_hashikami</a> クッション、ひょっとしてこれでいいのでは？説。</li></ul><h2 id="viozon-クッションテーブル-2026-09-26-土" tabindex="-1"><a class="header-anchor" href="#viozon-クッションテーブル-2026-09-26-土"><span>viozon クッションテーブル 2026-09-26 (土)</span></a></h2><p><a href="https://link.amazon/B0iStT463" target="_blank" rel="noopener noreferrer">amazon: viozon クッションテーブル</a></p><p>ビーズのクッションテーブルにジョイントのあるタブレットスタンドを組み合わせるのはどうなのか？と考えていた所、 まさにそういう製品が出ていたのでポチってみた。 良くあるクッションテーブルの上が、関節のあるタブレットスタンドみたいになっている製品。</p><p>これで下にBluetoothキーボードを置いて上にBOOX、をソファの上でやれるんじゃないか？と思い購入。</p><p>で、届いた。</p><p>下にキーボードを入れるには微妙にスペースが足りないか？ 入るんだが、指が上にあたる。やれなくはないんだが、微妙。 一方で膝の上にBOOXをたてるのは安定するので、最低限やりたかった事は出来ている。 これは、、、どうなんだろう？</p><p>角度を水平に近付けるとキーボードを打つスペースは確保出来る。 けれど水平に近付けるとソファで見るには少し角度が足りない。</p><p>あと一歩な気もするのでもう少し試行錯誤してみよう。</p><p>両手でがんばって調節したら、もっと高い位置に板を上げられた。 上げ過ぎるとバランスが悪くなるが、スペースはあけられるようになった。</p><p>これはいけるか？</p><p>丁度いい角度を見つけたかもしれない。これはいける。よしよし。</p><h2 id="ugreen-ピロースタンド-2026-06-17-水" tabindex="-1"><a class="header-anchor" href="#ugreen-ピロースタンド-2026-06-17-水"><span>UGREEN ピロースタンド 2026-06-17 (水)</span></a></h2><p><a href="https://www.amazon.co.jp/dp/B0963V5Q4Q?th=1&amp;linkCode=ll2&amp;tag=karino203-22&amp;linkId=4753edbe0507dd0698b96103a92d1331&amp;ref_=as_li_ss_tl" target="_blank" rel="noopener noreferrer">amazon: UGREEN タブレットスタンド ピロースタンド クッション</a></p><p>カインズの奴は送料が別途掛かるので、それならこれでいいか、とこちらを購入。2159円。実物は思ったより小さいがソファで膝の上に置くにはいい感じのサイズかもしれない。 ただキーボードを使うと揺れるな。キーボードの方は工夫がいるかも。</p><h3 id="当初の用途ではいまいちだが、まぁまぁ便利に使っている-2026-09-26-土" tabindex="-1"><a class="header-anchor" href="#当初の用途ではいまいちだが、まぁまぁ便利に使っている-2026-09-26-土"><span>当初の用途ではいまいちだが、まぁまぁ便利に使っている 2026-09-26 (土)</span></a></h3><p>結局ヒザの上では安定しないのでいまいちという結論に。</p><p>ただ大きなタブレットでも安定するスタンドとして、 お絵描きのリファレンスを置く時とか寝ながらyoutube見る時などには割と活躍している。 <a href="./LenovoTabP12.html">LenovoTabP12</a>はでかすぎて普通のタブレットスタンドでは不安があるが、 このピロースタンドならちゃんと安定する。 寝返りとかでちょっと当たった時にも倒れたりしないので布団の横のタブレット置き場としてはかなり良い。</p><p>また、当初はいらんだろう、と思った枕として使える機能が、ヨガマットで動画見つつ寝落ちしそうになった時にさっと枕になって地味に便利。 という事で期待した用途には使っていないが、割と使ってはいる。</p><h2 id="サンワダイレクト-ひざ上テーブル-2020年5月16日購入" tabindex="-1"><a class="header-anchor" href="#サンワダイレクト-ひざ上テーブル-2020年5月16日購入"><span>サンワダイレクト ひざ上テーブル(2020年5月16日購入)</span></a></h2><p>自分が買ったのはこれ。</p><p><a href="https://www.amazon.co.jp/dp/B01GF9N0D8?th=1&amp;linkCode=ll2&amp;tag=karino203-22&amp;linkId=22330c1cd7688d9209124ee34096d72c&amp;ref_=as_li_ss_tl" target="_blank" rel="noopener noreferrer">amazon: サンワダイレクト ひざ上テーブル ノートPC/タブレット用 15.6型対応</a></p><p>下に穴があいていて、これが長時間つかっていると暑い。 ただ思ったよりはいい感じで、そこらの板とかで代用するくらいなら買った方がいいと思う。 長時間使う時も下に挟むものとか工夫すれば普通に使えるし、当たり前だけどそのまま直接使うよりは全然快適。</p><p>個人的にはこの製品以外のもっと大きい奴も試してみたい気はしている。</p><p>買った当時のブログはこちら＞<a href="https://karino2.github.io/2020/05/20/improvehouselife.html" target="_blank" rel="noopener noreferrer">在宅環境改善グッズいろいろ - なーんだ、ただの水たまりじゃないか</a></p><h3 id="下に100均で買ったカゴを挟む" tabindex="-1"><a class="header-anchor" href="#下に100均で買ったカゴを挟む"><span>下に100均で買ったカゴを挟む</span></a></h3><p><a href="./背もたれクッション.html">背もたれクッション</a>の導入により長時間膝の上で作業する事が増えたので、 暑くなってくる問題に対処すべく100均一でカゴみたいなのを買って、その上に載せるようにしてみた。</p><p>少し安定感は落ちるがまったく熱は感じなくなったので、これでいいか、という感じ。</p><p>最初はダンボールを挟んでいたが、ダンボールよりプラスティックのカゴの方が断然快適。</p><p>追記： 2023年に引っ越してからは長時間は使わなくなったので下には何も挟まなくなった。</p><h3 id="一人ソファを使うようになってまた使用頻度が上がる" tabindex="-1"><a class="header-anchor" href="#一人ソファを使うようになってまた使用頻度が上がる"><span>一人ソファを使うようになってまた使用頻度が上がる</span></a></h3><p>親族がいらないから、ともらってきた一人用ソファを使うようになって、また膝の上テーブルを使うようになった。</p><h2 id="旅先でダンボールで自作" tabindex="-1"><a class="header-anchor" href="#旅先でダンボールで自作"><span>旅先でダンボールで自作</span></a></h2><p><a href="https://karino2.github.io/2024/01/07/diy_knee_table.html" target="_blank" rel="noopener noreferrer">ダンボールで膝の上テーブル自作 - なーんだ、ただの水たまりじゃないか</a></p><p>意外とダンボールで自作してもいい感じになった。最初からこれで良かったかもしれん。</p>`,39)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};